<script lang="ts">import Dialog from './Dialog.svelte';import Button from './Button.svelte';let { open = $bindable(false), title = 'Confirm', message = '', danger = false, onConfirm = () => {}, onCancel = () => {} }: { open?: boolean; title?: string; message?: string; danger?: boolean; onConfirm?: () => void; onCancel?: () => void } = $props();</script>{#if open}<Dialog {title} onClose={() => { open = false; onCancel(); }}><p>{message}</p><div class="row"><Button variant="secondary" onclick={() => { open = false; onCancel(); }}>Cancel</Button><Button variant={danger ? 'danger' : 'primary'} onclick={() => { open = false; onConfirm(); }}>Confirm</Button></div></Dialog>{/if}<style>p{color:var(--text-1)}.row{display:flex;justify-content:flex-end;gap:var(--space-3);margin-top:var(--space-5)}</style>
